with flattened_attrs as (select id, level, status_code, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, get_json_object(payload_json, '$.user.id') as user_id, coalesce(context['version'], 'none') as version_or_default from app_logs) select id, status_code, duration_sec, user_id, version_or_default, max(status_code) over (partition by level) as level_max_status_code, last_value(duration_sec) ignore nulls over (partition by level order by status_code, id rows between unbounded preceding and current row) as last_known_duration_sec, ntile(5) over (partition by level order by duration_sec, id) as duration_sec_bucket from flattened_attrs
